    })
    .collect();
let placed = report.count(orders);
Stack::gap(4).children((
    report
        .picker()
        .locale(DateLocale::of("en-IN"))
        .id("reports-refused-window")
        .title("Window"),
    refused,
    report
        .chart(Chart::bar("Orders").id("reports-refused-chart"))
        .locale("en-IN")
