/// A window of a conversation's messages, oldest first, and their files: the newest page,
/// the page before or after a cursor, or what came after the newest message a live list
/// has (at most [`LIVE_MESSAGES`]). Then whether older and newer messages lie beyond it.
///
/// A message's id is the row id SQLite gave it inside the transaction that wrote it, so
/// ids become visible in the order they commit, and "after the newest it has" can't skip
/// one (see [`crate::live`]).
pub async fn thread_window(
    uow: &(impl Executor + ?Sized),
    id: i64,
    ask: &LazyAsk,
) -> Result<(Vec<Message>, Vec<Attachment>, bool, bool)> {
    let query = Message::query().where_(Message::CONVERSATION_ID.eq(id));
    let rows = |records: navree::orm::Collection<Message>| -> Vec<Message> {
        records
            .into_vec()
            .into_iter()
            .map(|record| record.into_inner())
            .collect()
    };
    let (messages, older, newer) = match ask {
        LazyAsk::Before(text) if read_message_cursor(text).is_some() => {
            let cursor = read_message_cursor(text).unwrap_or_default();
            let mut found = rows(
                query
                    .where_(Message::ID.lt(cursor))
                    .order_by_desc("id")
                    .limit(MESSAGES + 1)
                    .get(uow)
                    .await?,
            );
            let more = found.len() as u64 > MESSAGES;
            found.truncate(MESSAGES as usize);
            found.reverse();
            (found, more, true)
        }
        LazyAsk::After(text) if read_message_cursor(text).is_some() => {
            let cursor = read_message_cursor(text).unwrap_or_default();
            let mut found = rows(
                query
                    .where_(Message::ID.gt(cursor))
                    .order_by("id")
                    .limit(MESSAGES + 1)
                    .get(uow)
                    .await?,
            );
            let more = found.len() as u64 > MESSAGES;
            found.truncate(MESSAGES as usize);
            (found, true, more)
        }
        LazyAsk::Since(text) => {
            let since = read_message_cursor(text).unwrap_or(i64::MAX);
            let mut found = rows(
                query
                    .where_(Message::ID.gt(since))
                    .order_by("id")
                    .limit(LIVE_MESSAGES + 1)
                    .get(uow)
                    .await?,
            );
            let more = found.len() as u64 > LIVE_MESSAGES;
            found.truncate(LIVE_MESSAGES as usize);
            (found, false, more)
        }
        _ => {
            let mut found = rows(
                query
                    .order_by_desc("id")
                    .limit(MESSAGES + 1)
                    .get(uow)
                    .await?,
            );
            let more = found.len() as u64 > MESSAGES;
            found.truncate(MESSAGES as usize);
            found.reverse();
            (found, more, false)
        }
    };
    let files = if messages.is_empty() {
        Vec::new()
    } else {
        Attachment::query()
            .where_(
                Attachment::MESSAGE_ID.is_in(messages.iter().map(|m| m.id).collect::<Vec<i64>>()),
            )
            .order_by("id")
            .get(uow)
            .await?
            .into_vec()
            .into_iter()
            .map(|record| record.into_inner())
            .collect()
    };
    Ok((messages, files, older, newer))
}

/// The command palette: the open conversation's actions, saved replies, and places.
pub fn palette(page: &Inbox<'_>) -> Command {
    let mut command = Command::new("palette")
        .title("Command palette")
        .placeholder("Type an action or a saved reply")
        .shortcut(true);
    if let Some(thread) = page.open {
        let id = thread.conversation.id;
        let status = Status::parse(&thread.conversation.status).unwrap_or(Status::Open);
        let mut actions = CommandGroup::new("This conversation")
            .item(
                CommandItem::run("Reply", Cmd::focus(COMPOSER_BODY))
                    .icon(icons::SEND)
                    .description("Write to the customer")
                    .not_recent(),
            )
            .item(
                CommandItem::post("Assign to me", format!("/inbox/{id}/assign/me"))
                    .icon(icons::USER_CHECK)
                    .keywords(["take", "mine"]),
            );
        actions = if status == Status::Closed {
            actions.item(
                CommandItem::post("Reopen", format!("/inbox/{id}/status/open"))
                    .icon(icons::ROTATE_CCW)
                    .not_recent(),
            )
        } else {
            actions
                .item(
                    CommandItem::post("Close", format!("/inbox/{id}/status/closed"))
                        .icon(icons::CIRCLE_CHECK)
                        .keywords(["resolve", "done"])
                        .not_recent(),
                )
                .item(
                    CommandItem::post("Mark pending", format!("/inbox/{id}/status/pending"))
                        .icon(icons::HOURGLASS)
                        .keywords(["waiting"])
                        .not_recent(),
                )
                .item(
                    CommandItem::post(
                        "Snooze until tomorrow",
                        format!("/inbox/{id}/snooze/tomorrow"),
                    )
                    .icon(icons::ALARM_CLOCK)
                    .not_recent(),
                )
        };
        for priority in [
            Priority::Urgent,
            Priority::High,
            Priority::Normal,
            Priority::Low,
        ] {
            if priority.key() != thread.conversation.priority {
                actions = actions.item(
                    CommandItem::post(
                        format!("Set priority to {}", priority.label().to_lowercase()),
                        format!("/inbox/{id}/priority/{}", priority.key()),
                    )
                    .icon(priority.icon())
                    .not_recent(),
                );
            }
        }
        command = command.group(actions);
        let mut replies = CommandGroup::new("Saved replies");
        for reply in &SAVED {
            replies = replies.item(
                CommandItem::run(
                    reply.title,
                    vec![Cmd::value(COMPOSER_SAVED, reply.key), Cmd::submit(COMPOSER)],
                )
                .id(format!("saved-{}", reply.key))
                .icon(icons::MESSAGE_SQUARE_TEXT)
                .description(crate::data::preview_of(reply.body))
                .keywords(["saved", "reply", "template"]),
            );
        }
        command = command.group(replies);
    }
    let mut places = CommandGroup::new("Go to");
    for view in View::ALL {
        places = places.item(
            CommandItem::link(view.label(), Filters::with_view(view).href("/inbox"))
                .icon(view.icon()),
        );
    }
    places = places.item(
        CommandItem::run("Keyboard shortcuts", Cmd::open("shortcuts"))
            .icon(icons::KEYBOARD)
            .not_recent(),
    );
    command.group(places)
}

/// One column as the board draws it: its cards, its count and limit, and what
/// ends it: a button for the next cards, or a note at the cap.
pub fn column(
    page: &ColumnPage,
    people: &[Person],
    viewer: &Person,
    filters: &Filters,
    today: NaiveDate,
) -> SortList {
    let column = page.column;
    let shown = page.start + page.cards.len();
    let mut list = SortList::new(column.key(), column.title())
        .items(page.cards.iter().enumerate().map(|(at, card)| {
            let item = SortItem::new(card.id.to_string(), card.title.clone())
                .body(card_face(card, people, today));
            // Under a filter, a card's move form counts in the whole column.
            match page.places.get(at) {
                Some(place) => item.position(*place),
                None => item,
            }
        }))
        .total(usize::try_from(page.total).unwrap_or(usize::MAX))
        .from(page.start)
        .empty(if filters.is_empty() {
            "No cards"
        } else {
            "No cards match"
        });
    if let Some(cursor) = &page.next {
        list = if shown >= CAP {
            list.end_note(format!(
                "Showing the first {CAP}. Filter the board, or press Ctrl K, to find the rest."
            ))
        } else {
            let mut fields = vec![
                ("after".to_owned(), cursor.clone()),
                ("show".to_owned(), (shown + PAGE).to_string()),
            ];
            fields.extend(filters.pairs());
            list.more(format!("/columns/{}", column.key()), fields)
        };
    }
    if let Some(limit) = column.limit() {
        list = list.limit(limit);
    }
    if column == Column::Done && !viewer.is_lead() {
        list = list.refuse("Only a lead can move cards to Done.");
    }
    list
}

/// One card as the board shows it: its labels, its title (which opens the drawer),
/// who has it, when it is due, its checklist and its comments.
pub fn card_face(card: &Card, people: &[Person], today: NaiveDate) -> Node {
    let labels = labels_of(&card.labels);
    let mut facts = Vec::new();
    if let Some(who) = person(people, card.assignee) {
        let first = who.name.split(' ').next().unwrap_or_default().to_owned();
        facts.push(Meta::new(first).start(Avatar::placeholder(who.name.clone()).size(Size::Sm)));
    }
    if card.checks_total > 0 {
        facts.push(Meta::icon(
            icons::LIST_CHECKS,
            format!("{}/{}", card.checks_done, card.checks_total),
        ));
    }
    if card.comments > 0 {
        facts.push(Meta::icon(icons::MESSAGE_SQUARE, card.comments.to_string()));
    }
    Stack::gap(2)
        .children((
            (!labels.is_empty() || card.due.is_some()).then(|| {
                Row::gap(1).wrap().children((
                    labels
                        .iter()
                        .map(|label| Badge::new(label.title()).tone(label.tone()).dot())
                        .collect::<Vec<_>>(),
                    card.due.map(|due| {
                        let (text, tone) = due_label(due, today);
                        Badge::new(text).variant(BadgeVariant::Outline).tone(tone)
                    }),
                ))
            }),
            open_card(card),
            Meta::list(facts),
        ))
        .into()
}

/// What the drawer and the card's page hold: the work on the left, the facts and
/// the history on the right; one column on a phone. `form` is the comment form as
/// it came back with an error, if it did.
pub fn card_detail(
    data: &CardData,
    viewer: &Person,
    today: NaiveDate,
    form: Option<FormView<CommentForm>>,
) -> Node {
    Grid::cols(3)
        .gap(6)
        .children((
            Stack::gap(6).span(2).children((
                Stack::gap(2).children((
                    Heading::h3("Description"),
                    Text::new(data.card.description.clone()),
                )),
                checklist(data),
                comments(data, form),
                history(data),
            )),
            Stack::gap(4).children((facts(data, today), move_form(&data.card, viewer))),
        ))
        .into()
}

/// The checklist: a bar for how much is done, and its lines, which tick and move.
pub fn checklist(data: &CardData) -> Node {
    let done = data.checks.iter().filter(|check| check.done == 1).count();
    let total = data.checks.len();
    let id = data.card.id;
    let lines = data.checks.iter().map(|check| {
        SortItem::new(check.id.to_string(), check.text.clone()).body(
            el("form")
                .attr("method", "post")
                .attr("action", format!("/checks/{}/done", check.id))
                .attr("id", format!("check-{}", check.id))
                .flag("data-ui-form", true)
                .uses(Uses::CORE)
                .child(
                    Row::gap(2).align(Align::Center).children((
                        Checkbox::new("done")
                            .checked(check.done == 1)
                            .id(format!("check-{}-box", check.id))
                            .on(Trigger::Change, Cmd::submit(format!("check-{}", check.id))),
                        el("label")
                            .attr("for", format!("check-{}-box", check.id))
                            .child(check.text.clone()),
                        el("noscript").child(Button::ghost("Save").size(Size::Xs).submit()),
                    )),
                ),
        )
    });
    Stack::gap(3)
        .id("checklist")
        .children((
            Row::gap(2).align(Align::Center).children((
                Heading::h3("Checklist"),
                (total > 0).then(|| Text::muted(format!("{done} of {total} done"))),
            )),
            (total > 0).then(|| {
                Progress::new(
                    u32::try_from(done).unwrap_or(0),
                    u32::try_from(total).unwrap_or(1),
                    "Checklist done",
                )
            }),
            Sortable::new(format!("checks-{id}"), "Checklist")
                .post(format!("/cards/{id}/checks/moves"))
                .heading(4)
                .list(
                    SortList::new("checks", "Checklist")
                        .hide_title()
                        .empty("No checklist yet")
                        .items(lines),
                ),
        ))
        .into()
}

/// The columns. A move posts to `/board/moves`, where the server checks it
/// against the board as it is then and gives the card a rank between its new
/// neighbours'.
pub fn columns(data: &BoardData, viewer: &Person, filters: &Filters, today: NaiveDate) -> Sortable {
    let mut pairs = filters.pairs();
    pairs.extend(shown_pairs(data));
    Sortable::new("columns", format!("{PROJECT} board"))
        .board()
        .post(moves_action(&pairs))
        .lists(
            data.columns
                .iter()
                .map(|page| column(page, &data.people, viewer, filters, today)),
        )
}

/// The board in its region: redrawn by the filters, and fetched again whenever the
/// event stream says the board changed, so other people's moves slide in. Its
/// source asks for as many cards in each column as the page holds.
pub fn board(data: &BoardData, viewer: &Person, filters: &Filters, today: NaiveDate) -> Region {
    let mut pairs = filters.pairs();
    pairs.extend(shown_pairs(data));
    Region::new(REGION)
        .src(format!("/fragments/board{}", query(&pairs)))
        .live_on(crate::live::stream().on(crate::live::TOPIC))
        .children(Stack::gap(2).children((live_state(), columns(data, viewer, filters, today))))
}
